vec2 hexCoords(vec2 p) {

    vec4 hC = floor(vec4(p, p - vec2(1, .5))/HEX.xyxy) +.5;

    vec4 h = vec4(p - hC.xy*HEX, p - (hC.zw + .5)*HEX);

